INSERT INTO #Item (AsCode,SecNum,ItemNum,QText,FullScore,CatCode,CatName) VALUES
(N'LG001',1,2,N'รูปสื่อ, โปรโมชันติดเรียบร้อยสวยงาม',1,N'SVC',N'การบริการ'),
(N'LG001',1,9,N'แคชเชียร์รับออเดอร์ลูกค้าได้ตลอดการขาย ห้ามหยุดปล่อยคิวลูกค้า (โดยให้ใช้บิลฉุกเฉินในกรณีที่ปิดรอบหรือเครื่อง POS  มีปัญหา)',1,N'OPS',N'กระบวนการทำงาน'),
(N'LG001',1,12,N'มี Service Mind หน้าตายิ้มแย้ม ใช้ถ้อยคำที่สุภาพ คำเรียกลูกค้าถูกต้อง เหมาะสม(เรียก "คุณลูกค้า" ใช้ได้กับลูกค้าทุกท่าน) ดูแลลูกค้าด้วยความใส่ใจ',2,N'SVC',N'การบริการ'),
(N'LG001',1,15,N'สอบถาม Member ทุกบิล / แนะนำการสมัครทุกครั้ง ( กรณีลูกค้ายังไม่มี )',5,N'SVC',N'การบริการ'),
(N'LG001',2,1,N'ตรวจเช็คสินค้าที่สเตชันและที่เก็บสต๊อก ได้คุณภาพ ไม่เกินอายุจัดเก็บ ไม่ยืดอายุสินค้า ',5,N'QLT',N'คุณภาพสินค้า'),
(N'LG001',2,8,N'Packaging มีครบถ้วน พร้อมใช้/ ใช้งานถูกต้อง',1,N'OPS',N'กระบวนการทำงาน'),
